import {
  AssessmentRounded,
  LogoutRounded,
  TimelineRounded,
  MemoryRounded,
  MonitorHeartRounded,
} from "@mui/icons-material";

import {
  Box,
  List,
  ListItemButton,
  ListItemIcon,
  ListItemText,
  Typography,
  Chip,
  Divider,
} from "@mui/material";

import { NavLink } from "react-router-dom";
import { ROUTES } from "../../routes/routes";
import logo from "../../assets/Eskom-logo-white.gif";

const navigation = [
  {
    title: "Forecast Intelligence",
    icon: TimelineRounded,
    path: ROUTES.FORECAST,
    badge: "Live",
  },
  {
    title: "Model Performance",
    icon: AssessmentRounded,
    path: ROUTES.MODEL_PERFORMANCE,
    badge: null,
  },
  {
    title: "System Health",
    icon: MemoryRounded,
    path: ROUTES.INFERENCE,
    badge: null,
  },
  {
    title: "Activity Monitor",
    icon: MonitorHeartRounded,
    path: ROUTES.INFERENCE_MONITORING,
    badge: "New",
  },
];

const DashboardSidebar = () => {
  return (
    <Box
      sx={{
        width: 320,
        height: "100vh",
        background: "linear-gradient(180deg, rgba(16, 29, 45, 0.95) 0%, rgba(10, 14, 39, 0.98) 100%)",
        backdropFilter: "blur(20px)",
        color: "#fff",
        display: "flex",
        flexDirection: "column",
        borderRight: "1px solid rgba(13, 99, 244, 0.15)",
        boxShadow: "4px 0 24px rgba(0, 0, 0, 0.3)",
        position: "relative",
        overflow: "hidden",
      }}
    >
      {/* Decorative gradient overlay */}
      <Box
        sx={{
          position: "absolute",
          top: 0,
          left: 0,
          right: 0,
          height: "300px",
          background: "radial-gradient(circle at 50% 0%, rgba(13, 99, 244, 0.15) 0%, transparent 70%)",
          pointerEvents: "none",
        }}
      />

      {/* Logo & Branding */}
      <Box
        sx={{
          px: 4,
          py: 4,
          position: "relative",
          zIndex: 1,
        }}
      >
        <Box
          component="img"
          src={logo}
          alt="Eskom"
          sx={{
            width: 160,
            mb: 2,
            filter: "drop-shadow(0 4px 12px rgba(13, 99, 244, 0.3))",
          }}
        />
        <Typography
          sx={{
            fontSize: "0.8125rem",
            color: "rgba(255, 255, 255, 0.5)",
            fontWeight: 600,
            letterSpacing: "0.5px",
            textTransform: "uppercase",
          }}
        >
          Forecast Command Center
        </Typography>
        <Typography
          sx={{
            fontSize: "0.75rem",
            color: "rgba(255, 255, 255, 0.3)",
            mt: 0.5,
          }}
        >
          Advanced Analytics & AI
        </Typography>
      </Box>

      <Divider
        sx={{
          borderColor: "rgba(255, 255, 255, 0.05)",
          mb: 2,
        }}
      />

      {/* Navigation */}
      <List
        sx={{
          px: 3,
          flex: 1,
          position: "relative",
          zIndex: 1,
        }}
      >
        {navigation.map((item) => {
          const Icon = item.icon;
          return (
            <ListItemButton
              key={item.path}
              component={NavLink}
              to={item.path}
              sx={{
                borderRadius: 3,
                mb: 1.5,
                py: 1.75,
                px: 2.5,
                position: "relative",
                overflow: "hidden",
                transition: "all 0.3s cubic-bezier(0.4, 0, 0.2, 1)",

                "&::before": {
                  content: '""',
                  position: "absolute",
                  top: 0,
                  left: 0,
                  right: 0,
                  bottom: 0,
                  background: "linear-gradient(135deg, rgba(13, 99, 244, 0.1) 0%, rgba(30, 94, 255, 0.05) 100%)",
                  opacity: 0,
                  transition: "opacity 0.3s ease",
                },

                "&:hover": {
                  background: "rgba(255, 255, 255, 0.05)",
                  transform: "translateX(4px)",

                  "&::before": {
                    opacity: 1,
                  },
                },

                "&.active": {
                  background: "linear-gradient(135deg, #0D63F4 0%, #1E5EFF 100%)",
                  boxShadow: "0 8px 24px rgba(13, 99, 244, 0.4), inset 0 1px 0 rgba(255, 255, 255, 0.2)",
                  transform: "translateX(4px)",

                  "&::after": {
                    content: '""',
                    position: "absolute",
                    left: 0,
                    top: "50%",
                    transform: "translateY(-50%)",
                    width: "4px",
                    height: "60%",
                    background: "#fff",
                    borderRadius: "0 4px 4px 0",
                  },
                },
              }}
            >
              <ListItemIcon
                sx={{
                  color: "inherit",
                  minWidth: 44,
                  "& .MuiSvgIcon-root": {
                    fontSize: "1.5rem",
                  },
                }}
              >
                <Icon />
              </ListItemIcon>

              <ListItemText
                primary={item.title}
                primaryTypographyProps={{
                  fontWeight: 700,
                  fontSize: "0.9375rem",
                }}
              />

              {item.badge && (
                <Chip
                  label={item.badge}
                  size="small"
                  sx={{
                    height: 22,
                    fontSize: "0.6875rem",
                    fontWeight: 700,
                    background: item.badge === "Live"
                      ? "linear-gradient(135deg, #16A34A 0%, #22C55E 100%)"
                      : "linear-gradient(135deg, #F59E0B 0%, #FBBF24 100%)",
                    color: "#fff",
                    border: "none",
                    boxShadow: item.badge === "Live"
                      ? "0 4px 12px rgba(22, 163, 74, 0.3)"
                      : "0 4px 12px rgba(245, 158, 11, 0.3)",
                  }}
                />
              )}
            </ListItemButton>
          );
        })}
      </List>

      {/* System Status */}
      <Box
        sx={{
          px: 3,
          pb: 2,
          position: "relative",
          zIndex: 1,
        }}
      >
        <Box
          sx={{
            background: "rgba(22, 163, 74, 0.15)",
            border: "1px solid rgba(22, 163, 74, 0.3)",
            borderRadius: 3,
            p: 2,
            mb: 2,
          }}
        >
          <Box
            sx={{
              display: "flex",
              alignItems: "center",
              gap: 1,
              mb: 1,
            }}
          >
            <Box
              sx={{
                width: 8,
                height: 8,
                borderRadius: "50%",
                background: "#16A34A",
                boxShadow: "0 0 12px rgba(22, 163, 74, 0.8)",
                animation: "pulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite",
                "@keyframes pulse": {
                  "0%, 100%": {
                    opacity: 1,
                  },
                  "50%": {
                    opacity: 0.5,
                  },
                },
              }}
            />
            <Typography
              sx={{
                fontSize: "0.8125rem",
                fontWeight: 700,
                color: "#16A34A",
              }}
            >
              All Systems Operational
            </Typography>
          </Box>
          <Typography
            sx={{
              fontSize: "0.75rem",
              color: "rgba(255, 255, 255, 0.4)",
            }}
          >
            Last updated: Just now
          </Typography>
        </Box>
      </Box>

      {/* Footer - Logout */}
      <Box
        sx={{
          p: 3,
          pt: 0,
          position: "relative",
          zIndex: 1,
        }}
      >
        <Divider
          sx={{
            borderColor: "rgba(255, 255, 255, 0.05)",
            mb: 2,
          }}
        />
        <ListItemButton
          sx={{
            borderRadius: 3,
            py: 1.5,
            background: "rgba(220, 38, 38, 0.1)",
            border: "1px solid rgba(220, 38, 38, 0.2)",

            "&:hover": {
              background: "rgba(220, 38, 38, 0.2)",
              border: "1px solid rgba(220, 38, 38, 0.3)",
            },
          }}
        >
          <ListItemIcon
            sx={{
              color: "#DC2626",
              minWidth: 44,
            }}
          >
            <LogoutRounded />
          </ListItemIcon>
          <ListItemText
            primary="Logout"
            primaryTypographyProps={{
              fontWeight: 600,
              color: "#DC2626",
            }}
          />
        </ListItemButton>
      </Box>
    </Box>
  );
};

export default DashboardSidebar;
